package main

import "fmt"

func Divide(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("divide failed: %v", r) // set named return
		}
	}()
	result = a / b
	return result, nil
}

func main() {
	_, err := Divide(10, 0)
	fmt.Println(err)
	// Output: divide failed: runtime error: integer divide by zero
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer func() { // recover INSIDE this goroutine
			if r := recover(); r != nil {
				fmt.Println("worker recovered:", r)
			}
		}()
		panic("in goroutine")
	}()
	wg.Wait()
	// Output: worker recovered: in goroutine
}

