package main

import "fmt"

// Divide converts a divide-by-zero panic into a normal error.
func Divide(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil { // only non-nil during a panic
			err = fmt.Errorf("divide failed: %v", r) // set the named return
		}
	}()
	result = a / b // panics when b == 0
	return result, nil
}

func main() {
	r, err := Divide(10, 0)
	fmt.Println(r, err) // 0 divide failed: runtime error: integer divide by zero
}

