package solution

import "fmt"

// SafeRun runs fn, converting any panic into a returned error.
func SafeRun(fn func()) (err error) {
	defer func() {
		if r := recover(); r != nil { // non-nil only during a panic
			err = fmt.Errorf("recovered: %v", r) // overwrite the named return
		}
	}()
	fn()        // if this panics, the deferred func runs and recovers
	return nil  // normal path: err stays nil
}

codeLab.testHarness:
package solution

import (
	"strings"
	"testing"
)

func TestSafeRunOK(t *testing.T) {
	if err := SafeRun(func() {}); err != nil {
		t.Fatalf("want nil, got %v", err)
	}
}

func TestSafeRunPanic(t *testing.T) {
	err := SafeRun(func() { panic("boom") })
	if err == nil || !strings.Contains(err.Error(), "boom") {
		t.Fatalf("want recovered error containing boom, got %v", err)
	}
}

func TestSafeRunNilDeref(t *testing.T) {
	err := SafeRun(func() {
		var p *int
		_ = *p // nil pointer dereference panics
	})
	if err == nil {
		t.Fatal("want recovered error, got nil")
	}
}

