func processAll(paths []string) error {
	for _, p := range paths {
		// closure creates a new function scope per iteration
		if err := func() error {
			f, err := os.Open(p)
			if err != nil {
				return err
			}
			defer f.Close() // runs at the END of THIS iteration's closure
			use(f)
			return nil
		}(); err != nil {
			return err
		}
	}
	return nil
}

import "fmt"

// Guard runs fn and returns its result. If fn panics, Guard recovers
// the panic and returns it as err, leaving result as T's zero value.
func Guard[T any](fn func() T) (result T, err error) {
	defer func() {
		if r := recover(); r != nil { // non-nil only during a panic
			if e, ok := r.(error); ok {
				err = fmt.Errorf("guard recovered: %w", e) // preserve error chain
			} else {
				err = fmt.Errorf("guard recovered: %v", r)
			}
		}
	}()
	result = fn() // if this panics, result stays the zero value of T
	return result, nil
}

import "log"

// Go runs fn in a new goroutine, recovering any panic so it
// can't take down the whole process.
func Go(fn func()) {
	go func() {
		defer func() {
			if r := recover(); r != nil { // catch panic in THIS goroutine
				log.Printf("recovered goroutine panic: %v", r)
			}
		}()
		fn() // a panic here unwinds into the deferred recover above
	}()
}
